struct TempFile { path: PathBuf }
impl TempFile {
    fn new() -> io::Result<Self> {
        let path = unique_path();
        File::create(&path)?;              // acquire, or nothing to own
        Ok(Self { path })
    }
}
impl Drop for TempFile {
    fn drop(&mut self) { let _ = fs::remove_file(&self.path); }  // infallible
}
